import pandas as pd

def get_top_performing_drivers(drivers: pd.DataFrame, vehicles: pd.DataFrame, trips: pd.DataFrame) -> pd.DataFrame:
    df = trips.merge(vehicles, on='vehicle_id').merge(drivers, on='driver_id')
    stats = df.groupby(['fuel_type', 'driver_id', 'accidents'], as_index=False).agg(
        rating=('rating', lambda x: round(x.mean(), 2)),
        distance=('distance', 'sum')
    )
    stats['rnk'] = stats.groupby('fuel_type').apply(
        lambda g: g.assign(
            rnk=g.sort_values(['rating', 'distance', 'accidents'], ascending=[False, False, True])['rating'].rank(method='min', ascending=False)
        )
    ).reset_index(drop=True)['rnk']

    # Sort and rank properly
    stats = stats.sort_values(by=['fuel_type', 'rating', 'distance', 'accidents'], ascending=[True, False, False, True])
    stats['rnk'] = stats.groupby('fuel_type').cumcount() + 1
    return stats[stats['rnk'] == 1][['fuel_type', 'driver_id', 'rating', 'distance']].sort_values('fuel_type')
